using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "VirtuelessRunModifier", menuName = "Data/RunModifiers/VirtuelessRunModifier", order = 0)]
public class VirtuelessRunModifier : RunModifier
{
	public override void InitializeNewRunBeforeResetAssetsToDefaultState()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.VirtuelessRunModifier = this;
	}

	public Rune[] GetCurrentRunesToNoVirtue()
	{
		Rune[] array = new Rune[7];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = new Rune("", 0, null, i);
		}
		return array;
	}
}
